const path = require("path");
const fs   = require("fs");

const W = 1200;
const H = 630;
const PINK  = "#FC74FE";
const DARK  = "#0D0D0D";
const WHITE = "#FFFFFF";

const BG     = "data:image/jpeg;base64,";
const FONT64 = "";

const bufToB64 = (b) => Buffer.from(b).toString("base64");
const dv = (style, children) => ({ type: "div", props: { style, children } });
const im = (src, w, h, st) => ({ type: "img", props: { src, width: w, height: h, style: st||{} } });

async function fetchToken(contract) {
  const def = { name: "Unknown Token", symbol: "TOKEN", logoURI: null };
  if (!contract) return def;
  try {
    const r = await fetch(`https://api.dexscreener.com/latest/dex/tokens/${contract}`,
      { signal: AbortSignal.timeout(5000) });
    if (!r.ok) return def;
    const d = await r.json();
    const p = d?.pairs?.[0];
    if (!p) return def;
    return { name: p.baseToken?.name||"Unknown Token",
             symbol: p.baseToken?.symbol||"TOKEN",
             logoURI: p.info?.imageUrl||null };
  } catch { return def; }
}

async function fetchLogo(url) {
  if (!url) return null;
  try {
    const r = await fetch(url, { signal: AbortSignal.timeout(4000) });
    if (!r.ok) return null;
    const buf = await r.arrayBuffer();
    if (buf.byteLength > 400000) return null;
    return `data:${r.headers.get("content-type")||"image/png"};base64,${bufToB64(buf)}`;
  } catch { return null; }
}

// ── Layout ────────────────────────────────────────────────────────────────────
// Стратегия: макет PNG как фон 1200x630
// Поверх — только 3 элемента:
//   1. Логотип токена в круге (перекрывает единорога)
//   2. Имя токена (перекрывает {token_name})
//   3. Тикер (перекрывает {$ticker})
//
// Координаты в 1200x630 (из pixel-debug):
//   Круг логотипа: center=(274,314), внешний r=214
//     Внутренний белый круг: center=(274,314), r~115
//   Token name: x=502, y=155, до x=1140
//   Ticker:     x=500, y=247, до x=620

function render(name, ticker, logoURI) {
  const nameLen = name.length;
  const nameFs  = nameLen > 18 ? 52 : nameLen > 12 ? 64 : nameLen > 8 ? 76 : 88;

  // Логотип — заполняет белый круг (r=115 → size=230, center 274,314)
  const logoEl = logoURI
    ? im(logoURI, 230, 230, { borderRadius: "50%", objectFit: "cover" })
    : dv({ width: 230, height: 230, borderRadius: "50%",
           backgroundColor: PINK,
           display: "flex", alignItems: "center", justifyContent: "center",
           fontSize: 72, fontWeight: 700, color: WHITE },
         name.slice(0, 2).toUpperCase());

  return dv({
    display: "flex", width: W, height: H,
    position: "relative",
  }, [

    // ── [0] Фон — оригинальный макет ─────────────────────────────────────────
    im(BG, W, H, { position: "absolute", top: 0, left: 0 }),

    // ── [1] Белый круг + логотип токена (поверх единорога) ───────────────────
    // Центр (274, 314), r=115 → left=159, top=199, size=230
    dv({
      position: "absolute",
      left: 164, top: 199,
      width: 230, height: 230,
      borderRadius: "50%",
      backgroundColor: WHITE,
      display: "flex", alignItems: "center", justifyContent: "center",
      overflow: "hidden",
    }, [logoEl]),

    // ── [2] Белый прямоугольник + имя токена ─────────────────────────────────
    // Перекрывает {token_name}: x=498, y=150, w=650, h=90
    dv({
      position: "absolute",
      left: 472, top: 155,
      width: 690, height: 80,
      backgroundColor: WHITE,
    }, ""),
    dv({
      position: "absolute",
      left: 476, top: 158,
      fontSize: nameFs, fontWeight: 700, color: DARK,
      lineHeight: 1, maxWidth: 640,
      overflow: "hidden",
    }, name),

    // ── [3] Белый прямоугольник + тикер ──────────────────────────────────────
    // Перекрывает {$ticker}: x=498, y=243, w=360, h=42
    dv({
      position: "absolute",
      left: 472, top: 242,
      width: 400, height: 38,
      backgroundColor: WHITE,
    }, ""),
    dv({
      position: "absolute",
      left: 476, top: 246,
      fontSize: 30, fontWeight: 700, color: PINK,
      lineHeight: 1,
    }, ticker),

  ]);
}

exports.handler = async (event) => {
  const { ImageResponse } = await import("@vercel/og");
  const contract = event.queryStringParameters?.contract || "";
  console.log("og-image:", contract);

  try {
    let fontData;
    try {
      const fp = path.join(__dirname, "font.ttf");
      fontData = fs.existsSync(fp) ? fs.readFileSync(fp) : Buffer.from(FONT64, "base64");
    } catch { fontData = Buffer.from(FONT64, "base64"); }

    const tok    = await fetchToken(contract);
    const logo   = await fetchLogo(tok.logoURI);
    const ticker = tok.symbol.startsWith("$") ? tok.symbol : `$${tok.symbol}`;

    const ir  = new ImageResponse(render(tok.name, ticker, logo), {
      width: W, height: H,
      fonts: [{ name: "Sans", data: fontData, weight: 700, style: "normal" }],
    });
    const png = Buffer.from(await ir.arrayBuffer());

    return {
      statusCode: 200,
      headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=3600" },
      body: png.toString("base64"),
      isBase64Encoded: true,
    };
  } catch (err) {
    console.error("ERROR:", err?.message, err?.stack?.slice(0, 300));
    return { statusCode: 500, body: "Error: " + err?.message };
  }
};
